USE os_job;
ALTER TABLE profiles ADD COLUMN photo_path VARCHAR(255) NULL;
CREATE TABLE IF NOT EXISTS skill_catalog (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO skill_catalog (name) VALUES ('Gestion de projet'),('Product Management'),('Product Ownership'),('Transformation digitale'),('Architecture SI'),('Management d’équipe'),('Méthode Agile'),('Scrum'),('PHP'),('MySQL'),('JavaScript'),('SEO'),('Marketing digital'),('Intelligence artificielle'),('Notion'),('Make'),('UX/UI Design'),('Gestion budgétaire'),('Leadership'),('Gestion des parties prenantes');
CREATE TABLE IF NOT EXISTS geo_locations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_id INT UNSIGNED NULL, kind ENUM('country','region','department','city') NOT NULL, name VARCHAR(150) NOT NULL, INDEX(parent_id), FOREIGN KEY(parent_id) REFERENCES geo_locations(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO geo_locations (id,parent_id,kind,name) VALUES (1,NULL,'country','France'),(2,1,'region','Provence-Alpes-Côte d’Azur'),(3,1,'region','Occitanie'),(4,2,'department','Bouches-du-Rhône'),(5,2,'department','Var'),(6,2,'department','Alpes-Maritimes'),(7,2,'department','Vaucluse'),(8,3,'department','Hérault'),(9,3,'department','Haute-Garonne'),(10,3,'department','Gard'),(11,3,'department','Pyrénées-Orientales'),(12,4,'city','Marseille'),(13,4,'city','Aix-en-Provence'),(14,5,'city','Toulon'),(15,6,'city','Nice'),(16,7,'city','Avignon'),(17,8,'city','Montpellier'),(18,9,'city','Toulouse'),(19,10,'city','Nîmes'),(20,11,'city','Perpignan') ON DUPLICATE KEY UPDATE name=VALUES(name);
CREATE TABLE IF NOT EXISTS profile_locations (profile_id BIGINT UNSIGNED NOT NULL, location_id INT UNSIGNED NOT NULL, PRIMARY KEY(profile_id,location_id), FOREIGN KEY(profile_id) REFERENCES profiles(id) ON DELETE CASCADE, FOREIGN KEY(location_id) REFERENCES geo_locations(id) ON DELETE CASCADE) ENGINE=InnoDB;
ALTER TABLE job_offers ADD COLUMN status VARCHAR(40) NOT NULL DEFAULT 'to_review';
ALTER TABLE job_offers ADD COLUMN updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
